// lib/data/krishna_data.dart
class KrishnaEvent {
  final String title;
  final String teluguTitle;
  final String description;
  final String teluguDescription;
  final String era;
  const KrishnaEvent({required this.title, required this.teluguTitle, required this.description, required this.teluguDescription, required this.era});
}

const List<KrishnaEvent> krishnaLifeEvents = [
  KrishnaEvent(title:'Birth in Mathura Prison',teluguTitle:'మధురలో జన్మ',era:'జన్మ',description:'Krishna was born as the 8th son of Devaki and Vasudeva in the prison of Kamsa in Mathura. On the night of his birth, all the guards fell asleep miraculously and the chains binding Vasudeva broke free.',teluguDescription:'కంసుని కారాగారంలో దేవకి వాసుదేవులకు 8వ పుత్రుడిగా కృష్ణుడు జన్మించాడు. జన్మించిన రాత్రి కాపలాదారులు నిద్రపోయారు, వాసుదేవుని సంకెళ్ళు విడిపోయాయి.'),
  KrishnaEvent(title:'Crossing Yamuna to Gokul',teluguTitle:'యమునా నదిని దాటి గోకులానికి',era:'జన్మ',description:'Vasudeva carried baby Krishna across the flooded Yamuna river to Gokul. The river parted to let them pass. Adishesha spread his hood to protect them from rain.',teluguDescription:'వాసుదేవుడు పసికందు కృష్ణుని వెంటపెట్టుకుని వరద యమునను దాటి గోకులానికి వెళ్ళాడు. ఆదిశేషుడు వారిని వర్షం నుండి రక్షించాడు.'),
  KrishnaEvent(title:'Putana Vadha',teluguTitle:'పూతన వధ',era:'బాల్యం',description:'The demoness Putana, sent by Kamsa, tried to kill baby Krishna by feeding him poisoned milk. Krishna sucked out her life force instead, killing her and liberating her soul.',teluguDescription:'కంసుడు పంపిన పూతన రాక్షసి విష స్తన్యం తాగించి శిశువు కృష్ణుని చంపడానికి ప్రయత్నించింది. కృష్ణుడు ఆమె ప్రాణాలు పీల్చుకుని ఆమెను వధించి మోక్షం ఇచ్చాడు.'),
  KrishnaEvent(title:'Trinavarta Vadha',teluguTitle:'తృణావర్త వధ',era:'బాల్యం',description:'The demon Trinavarta appeared as a whirlwind and carried baby Krishna into the sky. Krishna became immensely heavy, causing Trinavarta to fall and die.',teluguDescription:'తృణావర్త రాక్షసుడు సుడిగాలిగా వచ్చి శిశువు కృష్ణుని ఆకాశంలోకి తీసుకెళ్ళాడు. కృష్ణుడు అత్యంత బరువుగా మారి తృణావర్తుని పడగొట్టాడు.'),
  KrishnaEvent(title:'Damodara Leela - Tied to Mortar',teluguTitle:'దామోదర లీల',era:'బాల్యం',description:'Mother Yashoda, angry at mischievous Krishna for stealing butter, tied him to a mortar. Krishna dragged the mortar and uprooted two Arjuna trees, liberating two gandharvas cursed to be trees.',teluguDescription:'వెన్న దొంగిలించినందుకు కోపించిన యశోద కృష్ణుని రోటికి కట్టింది. కృష్ణుడు రోటిని లాగుతూ రెండు అర్జున వృక్షాలను పెకలించి, శాపగ్రస్తులైన గంధర్వులను విముక్తి చేసాడు.'),
  KrishnaEvent(title:'Kaliya Mardana',teluguTitle:'కాళియ మర్దన',era:'బాల్యం',description:'The poisonous serpent Kaliya had polluted the Yamuna river. Krishna dived into the river, danced on Kaliya\'s many hoods, subdued him, and ordered him to leave the Yamuna forever.',teluguDescription:'విషసర్పమైన కాళియుడు యమునా నదిని విషపూరితం చేశాడు. కృష్ణుడు నదిలో దూకి కాళియుని తలలపై నాట్యమాడి అతనిని అణచివేసి యమునను విడిచిపెట్టమని ఆదేశించాడు.'),
  KrishnaEvent(title:'Govardhan Parvata Dharana',teluguTitle:'గోవర్ధన పర్వత ధారణ',era:'బాల్యం',description:'Krishna lifted the Govardhan mountain on his little finger for 7 days to protect the villagers of Vrindavan from Indra\'s wrath and torrential rains. This event is celebrated as Govardhan Puja.',teluguDescription:'ఇంద్రుని కోపానికి గురైన వ్రిందావన గ్రామస్థులను రక్షించడానికి కృష్ణుడు 7 రోజులు గోవర్ధన పర్వతాన్ని తన చిటికెన వేలిపై ఎత్తాడు. ఇది గోవర్ధన పూజగా జరుపుతారు.'),
  KrishnaEvent(title:'Raas Leela - Divine Dance',teluguTitle:'రాస లీల',era:'యౌవనం',description:'Krishna performed the divine Raas dance with the gopis of Vrindavan under the full moon. This represents the soul\'s longing for union with the divine. Each gopi felt Krishna was dancing with her alone.',teluguDescription:'పౌర్ణమి రాత్రి కృష్ణుడు వ్రిందావన గోపికలతో దివ్యమైన రాస నృత్యం చేశాడు. ఇది ఆత్మ పరమాత్మతో ఏకత్వానికి నిరీక్షించడానికి ప్రతీక.'),
  KrishnaEvent(title:'Kamsa Vadha',teluguTitle:'కంస వధ',era:'యౌవనం',description:'Krishna and Balarama went to Mathura for Kamsa\'s wrestling tournament. Krishna killed the mighty wrestlers Chanura and Mushtika, then leaped upon the throne and killed Kamsa, fulfilling the prophecy.',teluguDescription:'కంసుని కుస్తీ పోటీకి కృష్ణ బలరాములు మధురకు వెళ్ళారు. కృష్ణుడు చాణూర ముష్టికులను చంపి, సింహాసనంపై దూకి కంసుని వధించాడు.'),
  KrishnaEvent(title:'Rukmini Vivaha',teluguTitle:'రుక్మిణి వివాహం',era:'యౌవనం',description:'Princess Rukmini of Vidarbha wrote a secret letter to Krishna expressing her love and requesting him to save her from an unwanted marriage. Krishna arrived, swept her away on his chariot and married her.',teluguDescription:'విదర్భ రాజకుమారి రుక్మిణి కృష్ణునికి రహస్య లేఖ రాసింది. కృష్ణుడు వచ్చి ఆమెను రథంపై తీసుకెళ్ళి వివాహం చేసుకున్నాడు.'),
  KrishnaEvent(title:'Syamantaka Mani Episode',teluguTitle:'శ్యమంతక మణి కథ',era:'యౌవనం',description:'The precious Syamantaka gem was stolen and Krishna was falsely accused. Krishna went on a long quest, killed the bear Jambavan, and returned the gem — also marrying Jambavan\'s daughter Jambavati.',teluguDescription:'శ్యమంతక మణి దొంగిలించబడి కృష్ణుడిపై అభియోగం వచ్చింది. కృష్ణుడు జాంబవంతుడిని ఓడించి మణిని తిరిగి తెచ్చి తన పవిత్రతను నిరూపించాడు.'),
  KrishnaEvent(title:'Arrival at Hastinapura - Pandavas\' Ambassador',teluguTitle:'హస్తినాపుర యాత్ర - శాంతి దూత',era:'మహాభారతం',description:'Before the Kurukshetra war, Krishna went as a peace ambassador to Hastinapura on behalf of the Pandavas. He proposed that the Pandavas be given just five villages. Duryodhana refused even a pinprick of land.',teluguDescription:'కురుక్షేత్ర యుద్ధానికి ముందు కృష్ణుడు పాండవుల తరపున శాంతి దూతగా హస్తినాపురానికి వెళ్ళాడు. పాండవులకు 5 గ్రామాలు ఇవ్వాలని కోరాడు. దుర్యోధనుడు సూది మొన పట్టే నేల కూడా ఇవ్వనని నిరాకరించాడు.'),
  KrishnaEvent(title:'Vishwaroopa Darshana to Dhritarashtra\'s Court',teluguTitle:'ధృతరాష్ట్ర సభలో విశ్వరూప దర్శనం',era:'మహాభారతం',description:'When Duryodhana tried to arrest Krishna in the court, Krishna showed his universal cosmic form (Vishwarupa) to the astonished Kauravas before disappearing. This was a warning of things to come.',teluguDescription:'దుర్యోధనుడు కృష్ణుని బంధించాలని ప్రయత్నించినప్పుడు, కృష్ణుడు సభలో విశ్వరూపం చూపించి అంతర్ధానమయ్యాడు.'),
  KrishnaEvent(title:'Bhagavad Gita Upadesha',teluguTitle:'భగవద్గీత ఉపదేశం',era:'కురుక్షేత్రం',description:'On the battlefield of Kurukshetra, when Arjuna was overwhelmed with grief, Krishna spoke the Bhagavad Gita — 700 verses of profound spiritual wisdom covering duty, devotion, knowledge, and liberation.',teluguDescription:'కురుక్షేత్ర యుద్ధభూమిలో నిరాశకు లోనైన అర్జునునికి కృష్ణుడు 700 శ్లోకాలతో కూడిన భగవద్గీత ఉపదేశించాడు.'),
  KrishnaEvent(title:'Arjuna\'s Charioteer in 18-Day War',teluguTitle:'18 రోజుల యుద్ధంలో అర్జుని సారథి',era:'కురుక్షేత్రం',description:'Krishna served as Arjuna\'s charioteer throughout the 18-day Kurukshetra war. Though he took a vow not to fight, he guided Arjuna strategically at every critical moment of the battle.',teluguDescription:'18 రోజుల కురుక్షేత్ర యుద్ధంలో కృష్ణుడు అర్జుని సారథిగా ఉన్నాడు. యుద్ధం చేయనని ప్రతిజ్ఞ చేసినా ప్రతి కీలక సమయంలో అర్జుని నిర్దేశించాడు.'),
  KrishnaEvent(title:'Karna\'s True Identity Revealed',teluguTitle:'కర్ణుని నిజ పరిచయం',era:'కురుక్షేత్రం',description:'Before the final battle with Karna, Krishna revealed to Arjuna that Karna is actually the eldest Pandava — son of Kunti. Arjuna was devastated. Krishna explained that Arjuna must still fight for dharma.',teluguDescription:'కర్ణుడు వాస్తవానికి కుంతీపుత్రుడు అని, పాండవులలో పెద్దవాడని కృష్ణుడు అర్జునికి చెప్పాడు. అర్జుని కదిలిపోయినా కృష్ణుడు ధర్మయుద్ధం కొనసాగించమని చెప్పాడు.'),
  KrishnaEvent(title:'Mausala Parva - Yadava Clan Destruction',teluguTitle:'మౌసల పర్వ - యాదవ వంశ నాశనం',era:'అంత్యం',description:'After the Kurukshetra war, the Yadava clan destroyed itself in a civil war. The sage Gandhari\'s curse came true. Krishna witnessed the destruction of his entire clan and wandered into the forest.',teluguDescription:'కురుక్షేత్ర యుద్ధం తర్వాత యాదవ వంశం పరస్పర యుద్ధంలో నాశనమైంది. గాంధారి శాపం నెరవేరింది. కృష్ణుడు తన వంశ నాశనాన్ని చూశాడు.'),
  KrishnaEvent(title:'Mahaprasthanam - Krishna\'s Final Departure',teluguTitle:'కృష్ణుని అంత్యకాలం',era:'అంత్యం',description:'Krishna sat in meditation in the forest. A hunter named Jara mistook his foot for a deer and shot an arrow. Krishna told the hunter not to fear, blessed him, and left his mortal body. He was 125 years old.',teluguDescription:'కృష్ణుడు అడవిలో ధ్యానంలో కూర్చున్నాడు. జర అనే వేటగాడు అతని పాదాన్ని లేడిగా పొరపడి బాణం వేశాడు. కృష్ణుడు వేటగాడిని అనుగ్రహించి దేహాన్ని విడిచాడు.'),
];

// lib/data/timeline_data.dart
class MahabharatamEvent {
  final String title;
  final String teluguTitle;
  final String era;
  final String teluguEra;
  final String description;
  final String teluguDescription;
  const MahabharatamEvent({required this.title, required this.teluguTitle, required this.era, required this.teluguEra, required this.description, required this.teluguDescription});
}

const List<MahabharatamEvent> mahabharatamTimeline = [
  // ORIGIN - Before Mahabharata
  MahabharatamEvent(title:'Shantanu falls in love with Ganga',teluguTitle:'శంతనుడు గంగను ప్రేమిస్తాడు',era:'Origin',teluguEra:'ఆరంభం',description:'King Shantanu of Hastinapura fell in love with the beautiful Ganga. She agreed to marry him on condition that he never questions her actions. They had 8 sons, 7 of whom she drowned. The 8th son was Bhishma (Devavrata).',teluguDescription:'హస్తినాపుర రాజు శంతనుడు సుందరి గంగను ప్రేమించాడు. 7 పుత్రులను ఆమె నదిలో వేసింది. 8వ పుత్రుడే దేవవ్రతుడు (భీష్ముడు).'),
  MahabharatamEvent(title:'Bhishma\'s Terrible Oath',teluguTitle:'భీష్మ ప్రతిజ్ఞ',era:'Origin',teluguEra:'ఆరంభం',description:'For his father Shantanu to marry fisherman\'s daughter Satyavati, Devavrata gave up his right to the throne and took a terrible vow of lifelong celibacy. This earned him the name Bhishma — the terrible oath.',teluguDescription:'తండ్రి శంతనుడు సత్యవతిని వివాహమాడేందుకు దేవవ్రతుడు రాజ్యాన్ని వదిలి జీవితకాల బ్రహ్మచర్య ప్రతిజ్ఞ చేశాడు. అందువల్ల అతనికి భీష్ముడనే పేరు వచ్చింది.'),
  MahabharatamEvent(title:'Birth of Dhritarashtra, Pandu, Vidura',teluguTitle:'ధృతరాష్ట్ర పాండు విదుర జన్మ',era:'Origin',teluguEra:'ఆరంభం',description:'Sage Vyasa, Satyavati\'s son, used Niyoga to sire children for the widowed queens. Ambika closed her eyes — Dhritarashtra was born blind. Ambalika turned pale — Pandu was born pale. The maid was calm — Vidura was born wise.',teluguDescription:'వ్యాస మహర్షి నియోగం ద్వారా అంబిక కళ్ళు మూసుకోవడంతో ధృతరాష్ట్రుడు గుడ్డిగా జన్మించాడు. అంబాలిక పాలిపోవడంతో పాండురాజు జన్మించాడు. దాసీ నిర్భయంగా ఉండడంతో విదురుడు జన్మించాడు.'),
  MahabharatamEvent(title:'Pandu\'s Curse and Retirement to Forest',teluguTitle:'పాండురాజు శాపం',era:'Origin',teluguEra:'ఆరంభం',description:'Pandu accidentally killed sage Kindama and his wife while hunting. The sage cursed that Pandu would die if he ever embraced his wife. Pandu retired to the Himalayas with his wives Kunti and Madri.',teluguDescription:'వేటలో పాండురాజు కింద్మ మహర్షి దంపతులను చంపాడు. శాపంతో భార్యను స్పర్శిస్తే చనిపోతావని శాపిచ్చాడు. పాండురాజు కుంతి మాద్రులతో హిమాలయాలకు వెళ్ళాడు.'),
  MahabharatamEvent(title:'Birth of Pandavas',teluguTitle:'పాండవుల జన్మ',era:'Origin',teluguEra:'ఆరంభం',description:'Kunti used a mantra given by sage Durvasa to invoke gods. Yudhishthira was born from Yama, Bhima from Vayu, Arjuna from Indra. Madri used the mantra twice and bore Nakula and Sahadeva from the Ashvins.',teluguDescription:'కుంతి దుర్వాస మంత్రంతో యమ వాయు ఇంద్రులను ప్రార్థించి యుధిష్ఠిర భీమ అర్జునులను పొందింది. మాద్రి అశ్వినీ దేవతల అనుగ్రహంతో నకుల సహదేవులను పొందింది.'),
  MahabharatamEvent(title:'Birth of Kauravas and Draupadi',teluguTitle:'కౌరవుల మరియు ద్రౌపది జన్మ',era:'Origin',teluguEra:'ఆరంభం',description:'Gandhari was upset that Kunti delivered first and struck her own womb. Vyasa divided the mass into 100 pieces — 100 Kauravas were born. Draupadi and Dhrishtadyumna were born from a sacrificial fire in Panchala.',teluguDescription:'గాంధారి కంటే ముందు కుంతి ప్రసవించడంతో గాంధారి తన గర్భాన్ని కొట్టుకుంది. వ్యాసుడు 100 ముక్కలు చేయడంతో 100 మంది కౌరవులు జన్మించారు. ద్రౌపది మరియు ధృష్టద్యుమ్నుడు యజ్ఞాగ్ని నుండి జన్మించారు.'),
  MahabharatamEvent(title:'Dronacharya\'s Gurukulam',teluguTitle:'ద్రోణాచార్యుని గురుకులం',era:'Youth',teluguEra:'యౌవనం',description:'Drona became the royal teacher of both Pandavas and Kauravas. Arjuna became his favourite student and the greatest archer. Ekalavya gave his thumb as gurudakshina to Drona.',teluguDescription:'ద్రోణుడు పాండవ కౌరవులకు రాజగురువయ్యాడు. అర్జుని అతనికి ప్రియ శిష్యుడు మరియు మహావిలుకాడయ్యాడు. ఏకలవ్యుడు గురుదక్షిణగా బొటన వేలు ఇచ్చాడు.'),
  MahabharatamEvent(title:'Rangabhoomi - The Grand Tournament',teluguTitle:'రంగభూమి - మహా పోటీ',era:'Youth',teluguEra:'యౌవనం',description:'In the graduation tournament, Arjuna displayed his archery skills brilliantly. Karna arrived and challenged Arjuna. Kripacharya asked for Karna\'s lineage. Duryodhana crowned Karna as king of Anga on the spot.',teluguDescription:'పట్టాభిషేక పోటీలో అర్జుని విలువిద్య ప్రదర్శించాడు. కర్ణుడు అర్జునిని సవాలు చేశాడు. దుర్యోధనుడు కర్ణుని అంగదేశ రాజుగా అభిషేకించాడు.'),
  MahabharatamEvent(title:'Lacquer House - Varanavata',teluguTitle:'లక్క ఇల్లు - వారణావత',era:'Exile 1',teluguEra:'మొదటి వనవాసం',description:'Duryodhana built a lacquer house (Lakshagraha) in Varanavata to burn the Pandavas alive. Vidura warned them in a coded message. The Pandavas escaped through a secret tunnel, setting fire to the house themselves.',teluguDescription:'దుర్యోధనుడు వారణావతలో లక్క ఇల్లు కట్టి పాండవులను సజీవంగా కాల్చాలని పన్నాగం పన్నాడు. విదురుడు సంకేత భాషలో హెచ్చరించాడు. పాండవులు రహస్య సొరంగం ద్వారా తప్పించుకున్నారు.'),
  MahabharatamEvent(title:'Hidimba Vadha and Marriage',teluguTitle:'హిడింబ వధ మరియు వివాహం',era:'Exile 1',teluguEra:'మొదటి వనవాసం',description:'The Rakshasa Hidimba attacked the Pandavas in the forest. Bhima killed him. Hidimba\'s sister Hidimbaa fell in love with Bhima. They married and had a son — the mighty Ghatotkacha.',teluguDescription:'రాక్షసుడు హిడింబుడు పాండవులను ఆక్రమించాడు. భీముడు అతనిని చంపాడు. హిడింబి భీముని ప్రేమించి వివాహం చేసుకుంది. వారికి ఘటోత్కచుడు జన్మించాడు.'),
  MahabharatamEvent(title:'Bakasura Vadha',teluguTitle:'బకాసుర వధ',era:'Exile 1',teluguEra:'మొదటి వనవాసం',description:'The Rakshasa Bakasura terrorized the village of Ekachakra, demanding regular offerings of food and humans. Bhima went in place of a Brahmin\'s family, fought Bakasura in a fierce battle, and killed him.',teluguDescription:'రాక్షసుడు బకాసురుడు ఏకచక్ర పట్టణాన్ని హింసిస్తూ బలులు కోరేవాడు. భీముడు బ్రాహ్మణ కుటుంబం తరపున వెళ్ళి బకాసురుని వధించాడు.'),
  MahabharatamEvent(title:'Draupadi Swayamvara',teluguTitle:'ద్రౌపది స్వయంవరం',era:'Marriage',teluguEra:'వివాహం',description:'Draupadi\'s swayamvara was held in Panchala. The test was to string a heavy bow and shoot a rotating fish target by looking at its reflection in water. Only Arjuna succeeded. Draupadi chose the Pandavas.',teluguDescription:'పాంచాలంలో ద్రౌపది స్వయంవరం జరిగింది. బరువైన ధనుస్సు ఎక్కుపెట్టి నీటిలో ప్రతిబింబాన్ని చూసి చేపను కొట్టాలి. అర్జుని మాత్రమే విజయం సాధించాడు.'),
  MahabharatamEvent(title:'Pandavas get Khandavaprastha',teluguTitle:'పాండవులకు ఖాండవప్రస్థం',era:'Kingdom',teluguEra:'రాజ్యం',description:'Dhritarashtra gave the Pandavas the barren land of Khandavaprastha. With Krishna\'s help, they built the magnificent city of Indraprastha in that land. Maya Danava built the magical palace for the Pandavas.',teluguDescription:'ధృతరాష్ట్రుడు పాండవులకు ఖాండవప్రస్థం ఇచ్చాడు. కృష్ణుని సహాయంతో అక్కడ ఇంద్రప్రస్థ నగరాన్ని నిర్మించారు. మయ దానవుడు మాయా సౌధం నిర్మించాడు.'),
  MahabharatamEvent(title:'Duryodhana Laughed at in Maya Sabha',teluguTitle:'మాయా సభలో దుర్యోధనుని అవమానం',era:'Kingdom',teluguEra:'రాజ్యం',description:'Duryodhana visited Indraprastha and was confused by the magical palace. He mistook water for floor and fell in. He mistook a crystal floor for water and hesitated. Draupadi laughed saying "the blind man\'s son is also blind."',teluguDescription:'దుర్యోధనుడు ఇంద్రప్రస్థాన్ని సందర్శించినప్పుడు మాయా సౌధంలో నేలను నీళ్ళని, నీళ్ళను నేల అని పొరపాటు పడ్డాడు. ద్రౌపది నవ్వి "గుడ్డివాని కొడుకు గుడ్డివాడే" అంది.'),
  MahabharatamEvent(title:'Dice Game - Gambling',teluguTitle:'జూద క్రీడ',era:'Exile 2',teluguEra:'వనవాసం',description:'Shakuni challenged Yudhishthira to a dice game. Yudhishthira lost everything — his kingdom, brothers, himself, and finally Draupadi. Duryodhana ordered Draupadi to be disrobed in the court. Bhima made a terrible vow.',teluguDescription:'శకుని యుధిష్ఠిరుని జూదానికి పిలిచాడు. యుధిష్ఠిరుడు రాజ్యం, సోదరులు, తనను తాను, చివరికి ద్రౌపదిని పణంగా పెట్టి ఓడిపోయాడు. ద్రౌపదిని సభలో అవమానించారు. భీముడు ప్రతిజ్ఞ చేశాడు.'),
  MahabharatamEvent(title:'12 Year Vanavasa + 1 Year Agnyatavasa',teluguTitle:'12 సంవత్సరాల వనవాసం + 1 సంవత్సరం అజ్ఞాతవాసం',era:'Exile 2',teluguEra:'వనవాసం',description:'The Pandavas were exiled for 13 years — 12 years in the forest and 1 year incognito. During this period Arjuna obtained divine weapons, Bhima killed Kichaka, and Yudhishthira answered Yaksha\'s questions.',teluguDescription:'పాండవులు 13 సంవత్సరాలు అరణ్యవాసం చేశారు — 12 సంవత్సరాలు అడవిలో, 1 సంవత్సరం అజ్ఞాతంలో. అర్జుని దివ్యాస్త్రాలు పొందాడు, భీముడు కీచకుని చంపాడు.'),
  MahabharatamEvent(title:'Krishna as Peace Ambassador',teluguTitle:'కృష్ణుని శాంతి దౌత్యం',era:'War Preparation',teluguEra:'యుద్ధ సన్నాహం',description:'Before the war, Krishna went to Hastinapura as a peace ambassador. He proposed giving the Pandavas just five villages. Duryodhana refused everything. Krishna showed his Vishwarupa and left.',teluguDescription:'యుద్ధానికి ముందు కృష్ణుడు శాంతి దూతగా హస్తినాపుర వెళ్ళాడు. 5 గ్రామాలు ఇవ్వాలని కోరాడు. దుర్యోధనుడు నిరాకరించాడు. కృష్ణుడు విశ్వరూపం చూపించి వెళ్ళాడు.'),
  MahabharatamEvent(title:'Kurukshetra War - 18 Days',teluguTitle:'కురుక్షేత్ర యుద్ధం - 18 రోజులు',era:'War',teluguEra:'యుద్ధం',description:'The great war lasted 18 days. Bhishma commanded for 10 days, Drona for 5 days, Karna for 2 days, and Shalya for 1 day. Ultimately all the Kauravas perished and the Pandavas were victorious.',teluguDescription:'మహా యుద్ధం 18 రోజులు జరిగింది. భీష్ముడు 10 రోజులు, ద్రోణుడు 5 రోజులు, కర్ణుడు 2 రోజులు, శల్యుడు 1 రోజు సేనాపతులు. చివరికి కౌరవులు నాశనమై పాండవులు విజయం పొందారు.'),
  MahabharatamEvent(title:'Pandavas Rule Hastinapura',teluguTitle:'పాండవుల పాలన',era:'After War',teluguEra:'యుద్ధానంతరం',description:'After the war, Yudhishthira was crowned king of Hastinapura. He performed the Ashvamedha Yajna. Dhritarashtra and Gandhari went to the forest for penance. Pandavas ruled righteously for 36 years.',teluguDescription:'యుద్ధం తర్వాత యుధిష్ఠిరుడు హస్తినాపుర రాజుగా పట్టాభిషేకమయ్యాడు. అశ్వమేధ యాగం చేసాడు. 36 సంవత్సరాలు ధర్మంగా పాలించాడు.'),
  MahabharatamEvent(title:'Mahaprasthanam - Final Journey',teluguTitle:'మహాప్రస్థానం',era:'After War',teluguEra:'యుద్ధానంతరం',description:'The Pandavas and Draupadi renounced the kingdom and set off on their final journey towards Mount Meru (heaven). One by one, all fell on the way except Yudhishthira. A dog followed them throughout — it was Dharma.',teluguDescription:'పాండవులు మరియు ద్రౌపది రాజ్యాన్ని విడిచి మేరు పర్వతం వైపు మహాప్రస్థానం చేశారు. ఒక్కొక్కరుగా పడిపోయారు. యుధిష్ఠిరుడు మాత్రం చివరివరకు నడిచాడు. అతనిని అనుసరించిన కుక్క ధర్మదేవుడే.'),
];

// 18-Day War Details
class WarDay {
  final int day;
  final String commanderKauravas;
  final String commanderPandavas;
  final String teluguCommanderKauravas;
  final String majorEvents;
  final String teluguMajorEvents;
  const WarDay({required this.day, required this.commanderKauravas, required this.commanderPandavas, required this.teluguCommanderKauravas, required this.majorEvents, required this.teluguMajorEvents});
}

const List<WarDay> kurukshetraWarDays = [
  WarDay(day:1,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'War begins. Arjuna hesitates, Krishna delivers Bhagavad Gita. Bhishma kills thousands. Arjuna wounds Bhishma slightly. Uttara dies.',teluguMajorEvents:'యుద్ధం మొదలు. అర్జుని నిరాశకు లోనవుతాడు. కృష్ణుడు గీత ఉపదేశిస్తాడు. భీష్ముడు వేలాదిమందిని చంపుతాడు.'),
  WarDay(day:2,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'Bhishma defeats many Pandava warriors. Arjuna fights bravely. Bhima shows tremendous power against the Kauravas.',teluguMajorEvents:'భీష్ముడు పాండవ యోధులను ఓడిస్తాడు. భీముడు కౌరవ సైన్యంలో ప్రళయం సృష్టిస్తాడు.'),
  WarDay(day:3,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'Bhishma arranges Garuda formation. Pandavas use crescent formation. Heavy casualties on both sides. Abhimanyu and Ghatatkacha fight brilliantly.',teluguMajorEvents:'భీష్ముడు గరుడ వ్యూహం పన్నుతాడు. పాండవులు అర్ధచంద్ర వ్యూహం ఏర్పాటు చేస్తారు. ఇరు వైపుల భారీ నష్టాలు.'),
  WarDay(day:4,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'Bhima kills 8 of Dhritarashtra\'s sons. Arjuna protects Bhima. Drona and Dhrishtadyumna duel. Iravan (Arjuna\'s son by Ulupi) is killed.',teluguMajorEvents:'భీముడు ధృతరాష్ట్రుని 8 మంది పుత్రులను చంపుతాడు. ఇరావంతుడు (అర్జుని పుత్రుడు) వీరమరణం పొందుతాడు.'),
  WarDay(day:5,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'Bhishma is unstoppable. Savyasachi (Arjuna) fights at full capacity. Satyaki and Bhima cause carnage among Kauravas.',teluguMajorEvents:'భీష్ముడు అజేయుడిగా ఉంటాడు. అర్జుని పూర్ణ శక్తితో పోరాడుతాడు.'),
  WarDay(day:6,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'Bhishma kills 10,000 warriors in one day. Pandavas are demoralized. Krishna consoles Yudhishthira. Night strategy meeting held.',teluguMajorEvents:'భీష్ముడు ఒక్కరోజులో 10,000 మంది వీరులను చంపుతాడు. పాండవులు నిరాశకు లోనవుతారు. రాత్రి వ్యూహ రచన.'),
  WarDay(day:7,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'Yudhishthira is wounded by Drona. Arjuna decides to fight more aggressively. Bhima kills 3 more of Dhritarashtra\'s sons.',teluguMajorEvents:'ద్రోణుడు యుధిష్ఠిరుని గాయపరుస్తాడు. అర్జుని మరింత తీవ్రంగా పోరాడాలని నిర్ణయిస్తాడు.'),
  WarDay(day:8,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'Ghatatkacha terrorizes Kaurava army at night. Iravan dies in battle. Arjuna breaks his vow and Krishna almost uses his Sudarshana Chakra. Bhishma\'s might seems unstoppable.',teluguMajorEvents:'ఘటోత్కచుడు రాత్రి కౌరవ సైన్యాన్ని భయభ్రాంతికి గురిచేస్తాడు. కృష్ణుడు సుదర్శన చక్రం తీయబోతాడు.'),
  WarDay(day:9,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'Bhishma defeats Pandava commanders one by one. Drona is invincible. Krishna advises Pandavas to ask Bhishma himself how to defeat him.',teluguMajorEvents:'భీష్ముడు పాండవ సేనాపతులను ఒక్కొక్కరిని ఓడిస్తాడు. కృష్ణుడు భీష్ముని దగ్గరే వెళ్ళి ఎలా ఓడించాలో అడగమని చెప్తాడు.'),
  WarDay(day:10,commanderKauravas:'Bhishma',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'భీష్ముడు',majorEvents:'BHISHMA FALLS. Shikhandi attacks Bhishma (Bhishma will not fight Shikhandi). Arjuna shoots arrows piercing Bhishma all over. Bhishma falls from his chariot on a bed of arrows.',teluguMajorEvents:'భీష్ముడు పడిపోతాడు! శిఖండి దాడి చేస్తాడు. అర్జుని బాణాల మీద భీష్ముడు పడతాడు. అమ్ముల పాన్పుపై ఉత్తరాయణం కోసం వేచి ఉంటాడు.'),
  WarDay(day:11,commanderKauravas:'Drona',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'ద్రోణుడు',majorEvents:'Drona takes command. He arrays the Chakravyuha formation. Drona vows to capture Yudhishthira. Abhimanyu learns of the Chakravyuha only to enter, not to exit.',teluguMajorEvents:'ద్రోణుడు సేనాపతి అవుతాడు. చక్రవ్యూహం ఏర్పాటు చేస్తాడు. అభిమన్యుడు చక్రవ్యూహంలో ప్రవేశించడం మాత్రమే నేర్చుకున్నాడు.'),
  WarDay(day:12,commanderKauravas:'Drona',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'ద్రోణుడు',majorEvents:'Drona again forms Chakravyuha. Abhimanyu enters the formation alone and causes massive destruction. Finally trapped by all Kaurava warriors, his chariot is broken, bow is cut, he fights with a chariot wheel and falls.',teluguMajorEvents:'ABHIMANYU VADHA. అభిమన్యుడు చక్రవ్యూహంలో ఒంటరిగా ప్రవేశించి అద్భుత పరాక్రమం చూపి అమర వీర మరణం పొందుతాడు.'),
  WarDay(day:13,commanderKauravas:'Drona',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'ద్రోణుడు',majorEvents:'Arjuna is enraged at Abhimanyu\'s death. He takes a vow to kill Jayadratha by sunset the next day or enter fire. The entire Kaurava army protects Jayadratha.',teluguMajorEvents:'అభిమన్యుని మరణానికి అర్జుని క్రోధం భగ్గుమంటుంది. జయద్రథుని సూర్యాస్తమయానికి ముందు చంపాలని ప్రతిజ్ఞ చేస్తాడు.'),
  WarDay(day:14,commanderKauravas:'Drona',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'ద్రోణుడు',majorEvents:'JAYADRATHA VADHA. Krishna hides the sun with his Sudarsana Chakra. Jayadratha emerges thinking Arjuna failed. Krishna removes chakra — sun reappears. Arjuna kills Jayadratha. Ghatotkacha dies killing Karna\'s Shakti weapon.',teluguMajorEvents:'జయద్రథ వధ. కృష్ణుడు సుదర్శన చక్రంతో సూర్యుని దాచాడు. అర్జుని జయద్రథుని చంపాడు. ఘటోత్కచుడు కర్ణుని శక్తి అస్త్రాన్ని భరించి మరణిస్తాడు.'),
  WarDay(day:15,commanderKauravas:'Drona',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'ద్రోణుడు',majorEvents:'DRONA VADHA. Yudhishthira falsely announces "Ashwatthama is dead" (killing an elephant named Ashwatthama). Drona lays down arms in grief. Dhrishtadyumna beheads him. Ashwatthama is enraged.',teluguMajorEvents:'ద్రోణ వధ. యుధిష్ఠిరుడు అశ్వత్థామ ఏనుగు చనిపోగా "అశ్వత్థామ మరణించాడు" అంటాడు. నిరాశతో ఆయుధాలు పెట్టిన ద్రోణుని ధృష్టద్యుమ్నుడు తలనరుకుతాడు.'),
  WarDay(day:16,commanderKauravas:'Karna',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'కర్ణుడు',majorEvents:'Karna takes command and fights brilliantly. Karna defeats Nakula, Sahadeva, Yudhishthira but spares them (promise to Kunti). Karna and Arjuna duel for the first time without decisive result.',teluguMajorEvents:'కర్ణుడు సేనాపతి అవుతాడు. నకుల సహదేవ యుధిష్ఠిరులను ఓడించి కుంతికి వాగ్దానం ప్రకారం వదిలిపెడతాడు.'),
  WarDay(day:17,commanderKauravas:'Karna',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'కర్ణుడు',majorEvents:'KARNA VADHA. Karna\'s chariot wheel sinks in the mud. He gets down to lift it. Arjuna hesitates. Krishna reminds him of all the adharma Karna participated in. Arjuna kills the defenseless Karna.',teluguMajorEvents:'కర్ణ వధ. కర్ణుని రథ చక్రం నేలలో దిగబడుతుంది. నిరాయుధ కర్ణుని అర్జుని చంపుతాడు. కృష్ణుడు ధర్మ స్మరణ చేయిస్తాడు.'),
  WarDay(day:18,commanderKauravas:'Shalya then Duryodhana',commanderPandavas:'Dhrishtadyumna',teluguCommanderKauravas:'శల్యుడు — దుర్యోధనుడు',majorEvents:'Shalya is killed by Yudhishthira. Shakuni is killed by Sahadeva. Duryodhana hides in a lake. Finally Bhima breaks Duryodhana\'s thighs with his mace — fulfilling his vow. WAR ENDS.',teluguMajorEvents:'శల్యుడు చనిపోతాడు. శకుని సహదేవుని చేతిలో మరణిస్తాడు. భీముడు దుర్యోధనుని తొడలు విరిచి ప్రతిజ్ఞ నెరవేర్చుతాడు. యుద్ధం ముగుస్తుంది.'),
];
